with filtered_suppliers as (select *, concat(city, '/', country) as city_country from suppliers where rating between 2.6 and 3.3 and rating is null), Summary as (select country, round((100 * sum(case when country = 'US' then 1 else 0 end)) / count(*), 1) as pct_us, count(rating) as rating_count from filtered_suppliers group by country) select country, pct_us from Summary where rating_count < 8 order by pct_us desc
